// Package cleanup classifies subdirectories of a scanned tree into cleanup
// candidates: "safe" (regenerated by their tool), "review_first" (probably
// disposable, a human should look) and "keep" (big, but must not be deleted
// by hand: shown so the user understands where the space went and how to
// reclaim it properly).
// It is a heuristic layer on top of a scan; it never mutates anything.
package cleanup

import (
	"os"
	"path/filepath"
	"sort"
	"strings"

	"disklens/internal/scanner"
)

// Candidate is one cleanup candidate found in the tree.
type Candidate struct {
	Name     string `json:"name"`
	Path     string `json:"path"`
	Category string `json:"category"`
	Status   string `json:"status"` // "safe", "review_first" or "keep"
	Hint     string `json:"hint"`
	Apparent int64  `json:"size_apparent_bytes"`
	Disk     int64  `json:"size_disk_bytes"`
	Files    int64  `json:"files"`
	Dirs     int64  `json:"dirs"`
}

type rule struct {
	name     string // exact directory name, matched case-insensitively
	category string
	status   string
	hint     string
	// markers: if non-empty, the parent directory must contain at least one of
	// these files for the rule to apply (context check, e.g. node_modules
	// only counts as safe next to a package.json).
	markers []string
	// pathAny: if non-empty, the lowercase full path must contain at least one
	// of these substrings (context check for generic directory names).
	pathAny []string
	// never: subtree is skipped entirely and never reported.
	never bool
}

var rules = []rule{
	{name: ".git", never: true},
	{name: "node_modules", category: "dependencies", status: "safe",
		hint:    "recreated by npm/pnpm install",
		markers: []string{"package.json", "package-lock.json", "pnpm-lock.yaml", "yarn.lock"}},
	{name: ".venv", category: "python venv", status: "safe",
		hint:    "recreated by: python -m venv .venv",
		markers: []string{"pyproject.toml", "requirements.txt"}},
	{name: "venv", category: "python venv", status: "safe",
		hint:    "recreated by: python -m venv venv",
		markers: []string{"pyproject.toml", "requirements.txt"}},
	{name: "__pycache__", category: "python bytecode", status: "safe", hint: "regenerated automatically"},
	{name: ".pytest_cache", category: "test cache", status: "safe", hint: "regenerated automatically"},
	{name: ".mypy_cache", category: "type cache", status: "safe", hint: "regenerated automatically"},
	{name: ".ruff_cache", category: "linter cache", status: "safe", hint: "regenerated automatically"},
	{name: ".ipynb_checkpoints", category: "jupyter cache", status: "safe", hint: "regenerated automatically"},
	{name: "target", category: "rust build output", status: "safe",
		hint: "recreated by cargo build", markers: []string{"Cargo.toml"}},
	{name: "dist", category: "build output", status: "review_first",
		hint: "recreated by the project's build; check if it ships artifacts"},
	{name: "build", category: "build output", status: "review_first",
		hint: "recreated by the project's build; check first"},
	{name: ".cache", category: "cache", status: "safe", hint: "regenerated by the owning tool"},
	{name: "Temp", category: "temp files", status: "review_first", hint: "usually disposable; glance at contents first"},
	{name: "npm-cache", category: "npm cache", status: "safe", hint: "re-downloaded on demand (npm cache)"},
	{name: "pip", category: "pip cache", status: "safe",
		hint: "re-downloaded on demand (pip cache); only counts under an AppData\\Local\\pip path"},

	// ML tooling: model files are big and re-downloadable, but which ones the
	// user still needs is a judgement call — always review_first.
	{name: "models", category: "ml models", status: "review_first",
		hint:    "large model files; re-downloadable but verify which ones you still need",
		pathAny: []string{"comfy", "ollama", "llama", "huggingface", "stable-diffusion", "sd-webui", "a1111", "gpt4all", "text-generation-webui", "koboldcpp"}},
	{name: "checkpoints", category: "ml checkpoints", status: "review_first",
		hint:    "training checkpoints / model weights; verify before deleting",
		pathAny: []string{"comfy", "ollama", "llama", "huggingface", "stable-diffusion", "sd-webui", "a1111"}},
	{name: "custom_nodes", category: "comfyui extensions", status: "review_first",
		hint: "ComfyUI custom nodes; reinstallable but may hold local state", pathAny: []string{"comfy"}},
	{name: "input", category: "comfyui input", status: "review_first",
		hint: "ComfyUI input images; usually copies of your own photos", pathAny: []string{"comfy"}},

	// --- Windows system locations: big, but never delete by hand. ---
	{name: "winsxs", category: "windows component store", status: "keep", pathAny: []string{`\windows\winsxs`},
		hint: "most files are hard links shared with System32, so deleting would free far less than shown; " +
			"reclaim with: Dism /Online /Cleanup-Image /StartComponentCleanup"},
	{name: "installer", category: "windows installer cache", status: "keep", pathAny: []string{`\windows\installer`},
		hint: "needed to repair, update and uninstall programs; never delete manually (use Disk Cleanup)"},
	{name: "$recycle.bin", category: "recycle bin", status: "keep",
		hint: "already-deleted files; empty the Recycle Bin instead (x in the TUI, empty_recycle_bin via MCP)"},
	{name: "system volume information", category: "restore points", status: "keep",
		hint: "System Restore / shadow copies; manage in System Protection settings"},
	{name: "windows.old", category: "previous windows install", status: "review_first",
		hint: "remove via Settings > System > Storage > Temporary files (\"Previous Windows installation\"); rollback is lost"},
	{name: "softwaredistribution", category: "windows update cache", status: "keep", pathAny: []string{`\windows\softwaredistribution`},
		hint: "clean via Disk Cleanup > Windows Update Cleanup"},

	// --- Per-user caches on Windows. ---
	{name: "crashdumps", category: "crash dumps", status: "safe", pathAny: []string{`appdata\local\crashdumps`},
		hint: "application crash dumps; only useful for debugging"},
	{name: "d3dscache", category: "shader cache", status: "safe", pathAny: []string{`appdata\local\d3dscache`},
		hint: "DirectX shader cache; rebuilt on demand"},
	{name: "dxcache", category: "shader cache", status: "safe", pathAny: []string{"nvidia", "amd"},
		hint: "GPU driver shader cache; rebuilt on demand"},
	{name: "glcache", category: "shader cache", status: "safe", pathAny: []string{"nvidia", "amd"},
		hint: "GPU driver shader cache; rebuilt on demand"},
	{name: "shadercache", category: "shader cache", status: "safe", pathAny: []string{"steam"},
		hint: "Steam shader pre-cache; re-downloaded/rebuilt on demand"},
	{name: "inetcache", category: "browser cache", status: "safe", pathAny: []string{`microsoft\windows\inetcache`},
		hint: "legacy IE/WebView cache; rebuilt on demand"},
	{name: "cache", category: "browser cache", status: "safe", pathAny: browserLike,
		hint: "browser/Electron app cache; recreated automatically (close the app first)"},
	{name: "code cache", category: "browser cache", status: "safe", pathAny: browserLike,
		hint: "compiled JavaScript cache; recreated automatically (close the app first)"},
	{name: "gpucache", category: "browser cache", status: "safe", pathAny: browserLike,
		hint: "GPU shader cache; recreated automatically (close the app first)"},
	{name: "service worker", category: "browser cache", status: "review_first", pathAny: browserLike,
		hint: "offline data of websites; sites re-download it, but offline web apps lose local state"},

	// --- Developer caches. ---
	{name: "caches", category: "gradle cache", status: "safe", pathAny: []string{`.gradle\caches`},
		hint: "re-downloaded by the next Gradle build"},
	{name: "packages", category: "nuget cache", status: "safe", pathAny: []string{`.nuget\packages`},
		hint: "re-downloaded by dotnet restore"},
	{name: "go-build", category: "go build cache", status: "safe",
		hint: "Go build cache; rebuilt on demand (go clean -cache)"},
	{name: "store", category: "pnpm store", status: "review_first", pathAny: []string{"pnpm"},
		hint: "shared pnpm package store; prefer: pnpm store prune"},
	{name: "yarn", category: "yarn cache", status: "safe", pathAny: []string{`appdata\local\yarn`},
		hint: "re-downloaded on demand (yarn cache clean)"},
	{name: "docker", category: "docker data", status: "keep", pathAny: []string{`appdata\local\docker`},
		hint: "Docker Desktop disk image (*.vhdx) lives here; reclaim with docker system prune, then " +
			"Docker Desktop > Troubleshoot > Clean / Purge data — never delete the vhdx directly"},
	{name: "packages", category: "wsl distributions", status: "keep", pathAny: []string{`appdata\local\packages\canonical`},
		hint: "WSL distribution disks (ext4.vhdx); manage with wsl --unregister / compact the vhdx"},
}

// browserLike: path fragments of Chromium-based browsers and Electron apps
// whose Cache/Code Cache/GPUCache folders are safe to drop.
var browserLike = []string{
	`google\chrome`, `microsoft\edge`, `bravesoftware`, `opera software`, `vivaldi`, `yandex\yandexbrowser`,
	`appdata\roaming\discord`, `appdata\roaming\slack`, `appdata\roaming\code`, `microsoft\teams`,
	`appdata\roaming\spotify`, `appdata\local\spotify`, `appdata\roaming\telegram desktop`,
}

// Classify walks root's subtree (root itself is not reported) and returns
// candidates sorted by disk size, largest first. Matched subtrees are not
// descended into, so a huge node_modules reports once, not a thousand times.
func Classify(root *scanner.Node) []Candidate {
	var out []Candidate
	var walk func(*scanner.Node)
	walk = func(n *scanner.Node) {
		for _, c := range n.Children {
			low := strings.ToLower(c.Name)
			r := ruleFor(low, c.Path)
			if r != nil {
				if !r.never {
					out = append(out, Candidate{
						Name: c.Name, Path: c.Path, Category: r.category, Status: r.status, Hint: r.hint,
						Apparent: c.Size, Disk: c.Disk, Files: c.Files, Dirs: c.Dirs,
					})
				}
				continue
			}
			walk(c)
		}
	}
	walk(root)
	sort.Slice(out, func(i, j int) bool { return out[i].Disk > out[j].Disk })
	return out
}

func ruleFor(lowName, dirPath string) *rule {
	low := normPath(dirPath)
	for i := range rules {
		r := &rules[i]
		if r.name != lowName {
			continue
		}
		if len(r.markers) > 0 && !hasMarker(filepath.Dir(dirPath), r.markers) {
			continue
		}
		// "pip" is only the pip cache when it lives in an AppData\Local\pip shape.
		if r.name == "pip" && !strings.Contains(low, `appdata\local\pip`) {
			continue
		}
		if len(r.pathAny) > 0 {
			hit := false
			for _, s := range r.pathAny {
				if strings.Contains(low, s) {
					hit = true
					break
				}
			}
			if !hit {
				continue // another rule with the same name may still match
			}
		}
		return r
	}
	return nil
}

func hasMarker(parentDir string, markers []string) bool {
	for _, m := range markers {
		if _, err := os.Stat(filepath.Join(parentDir, m)); err == nil {
			return true
		}
	}
	return false
}

// normPath lowercases a path and uses backslashes, so pathAny fragments
// (written Windows-style) match on every OS and in tests.
func normPath(p string) string {
	return strings.ReplaceAll(strings.ToLower(p), "/", `\`)
}
